/**
 * Punto de entrada y composition root. No contiene lógica de negocio.
 */
export function execute(input: Record<string, string>): Record<string, string> {
  const evaluator = new LoanEvaluator(
    new LoanValidationPolicy(),
    new AnnualRateCalculator(),
    new FrenchAmortization(),
    new InsurancePolicy(),
    new LoanTotals(),
  );
  const useCase = new EvaluateLoanService(evaluator, new InMemoryAuditLog());
  const application = new LoanInputMapper().toApplication(input);
  return new LoanOutputMapper().toOutput(useCase.execute(application));
}

/**
 * Entrada técnicamente malformada (campo ausente o con formato inválido).
 * No representa un rechazo de negocio.
 */
export class InvalidLoanInputError extends Error {
  readonly field: string;

  constructor(field: string) {
    super('Entrada inválida para el campo ' + field);
    this.name = 'InvalidLoanInputError';
    this.field = field;
  }
}

import type { Decimal } from '../shared/decimal.ts';

/**
 * Solicitud de préstamo (value object inmutable).
 */
export class LoanApplication {
  readonly principal: Decimal;
  readonly termMonths: Decimal;
  readonly creditScore: Decimal;
  readonly customerAge: Decimal;

  constructor(principal: Decimal, termMonths: Decimal, creditScore: Decimal, customerAge: Decimal) {
    this.principal = principal;
    this.termMonths = termMonths;
    this.creditScore = creditScore;
    this.customerAge = customerAge;
  }

  termMonthsAsInteger(): number {
    return this.termMonths.toInteger();
  }
}

import { Decimal } from '../shared/decimal.ts';
import type { RejectionCode } from './RejectionCode.ts';

export type LoanStatus = 'APPROVED' | 'REJECTED';

const ZERO_RATE = Decimal.of(0).setScale(4, 'DOWN');
const ZERO_AMOUNT = Decimal.of(0).setScale(2, 'DOWN');

/**
 * Resultado de la evaluación de un préstamo (value object).
 */
export class LoanEvaluation {
  readonly status: LoanStatus;
  readonly errorCode: string;
  readonly annualRate: Decimal;
  readonly monthlyPayment: Decimal;
  readonly insurance: Decimal;
  readonly totalInterest: Decimal;
  readonly totalPaid: Decimal;

  constructor(
    status: LoanStatus,
    errorCode: string,
    annualRate: Decimal,
    monthlyPayment: Decimal,
    insurance: Decimal,
    totalInterest: Decimal,
    totalPaid: Decimal,
  ) {
    this.status = status;
    this.errorCode = errorCode;
    this.annualRate = annualRate;
    this.monthlyPayment = monthlyPayment;
    this.insurance = insurance;
    this.totalInterest = totalInterest;
    this.totalPaid = totalPaid;
  }

  /**
   * Solicitud aprobada: código de error vacío e importes calculados.
   * @rule R-015
   */
  static approved(
    annualRate: Decimal,
    monthlyPayment: Decimal,
    insurance: Decimal,
    totalInterest: Decimal,
    totalPaid: Decimal,
  ): LoanEvaluation {
    return new LoanEvaluation('APPROVED', '', annualRate, monthlyPayment, insurance, totalInterest, totalPaid);
  }

  /**
   * Solicitud rechazada: código de error y tasa e importes en cero.
   * @rule R-015
   * @rule R-004
   */
  static rejected(code: RejectionCode): LoanEvaluation {
    return new LoanEvaluation('REJECTED', code, ZERO_RATE, ZERO_AMOUNT, ZERO_AMOUNT, ZERO_AMOUNT, ZERO_AMOUNT);
  }
}

import type { LoanApplication } from './LoanApplication.ts';
import type { RejectionCode } from './RejectionCode.ts';

/**
 * Causa de rechazo: isViolatedBy es verdadero cuando la solicitud debe rechazarse.
 */
export interface RejectionSpecification {
  readonly code: RejectionCode;
  isViolatedBy(application: LoanApplication): boolean;
}

import { Decimal } from '../shared/decimal.ts';
import type { LoanApplication } from './LoanApplication.ts';
import type { RejectionCode } from './RejectionCode.ts';
import type { RejectionSpecification } from './RejectionSpecification.ts';

export class PrincipalRangeSpecification implements RejectionSpecification {
  readonly code: RejectionCode = 'E01';
  private readonly min: Decimal = Decimal.of('1000.00');
  private readonly max: Decimal = Decimal.of('500000.00');

  /**
   * Monto fuera del rango inclusivo 1000.00 a 500000.00.
   * @rule R-001
   */
  isViolatedBy(application: LoanApplication): boolean {
    return application.principal.lt(this.min) || application.principal.gt(this.max);
  }
}

import { Decimal } from '../shared/decimal.ts';
import type { LoanApplication } from './LoanApplication.ts';
import type { RejectionCode } from './RejectionCode.ts';
import type { RejectionSpecification } from './RejectionSpecification.ts';

export class TermRangeSpecification implements RejectionSpecification {
  readonly code: RejectionCode = 'E02';
  private readonly min: Decimal = Decimal.of(6);
  private readonly max: Decimal = Decimal.of(360);

  /**
   * Plazo fuera del rango inclusivo 6 a 360 meses.
   * @rule R-002
   */
  isViolatedBy(application: LoanApplication): boolean {
    return application.termMonths.lt(this.min) || application.termMonths.gt(this.max);
  }
}

import { Decimal } from '../shared/decimal.ts';
import type { LoanApplication } from './LoanApplication.ts';
import type { RejectionCode } from './RejectionCode.ts';
import type { RejectionSpecification } from './RejectionSpecification.ts';

export class MaturityAgeSpecification implements RejectionSpecification {
  readonly code: RejectionCode = 'E03';
  private readonly maxAge: Decimal = Decimal.of(75);
  private readonly monthsPerYear: Decimal = Decimal.of(12);

  /**
   * Edad al vencimiento mayor que 75 (años del plazo truncados).
   * @rule R-003
   */
  isViolatedBy(application: LoanApplication): boolean {
    return this.maturityAge(application).gt(this.maxAge);
  }

  /**
   * WS-MATURITY-AGE = edad + parte entera de plazo / 12.
   * @rule R-003
   */
  maturityAge(application: LoanApplication): Decimal {
    const termYears = application.termMonths.dividedBy(this.monthsPerYear, 0, 'DOWN');
    return application.customerAge.plus(termYears);
  }
}

import { Decimal } from '../shared/decimal.ts';
import type { LoanApplication } from './LoanApplication.ts';
import type { RejectionCode } from './RejectionCode.ts';
import type { RejectionSpecification } from './RejectionSpecification.ts';

export class MinimumCreditScoreSpecification implements RejectionSpecification {
  readonly code: RejectionCode = 'E04';
  private readonly minScore: Decimal = Decimal.of(550);

  /**
   * Puntaje menor que 550 se rechaza.
   * @rule R-005
   */
  isViolatedBy(application: LoanApplication): boolean {
    return application.creditScore.lt(this.minScore);
  }
}

import type { LoanApplication } from './LoanApplication.ts';
import type { RejectionCode } from './RejectionCode.ts';
import type { RejectionSpecification } from './RejectionSpecification.ts';
import { PrincipalRangeSpecification } from './PrincipalRangeSpecification.ts';
import { TermRangeSpecification } from './TermRangeSpecification.ts';
import { MaturityAgeSpecification } from './MaturityAgeSpecification.ts';
import { MinimumCreditScoreSpecification } from './MinimumCreditScoreSpecification.ts';

/**
 * Aplica las causas de rechazo en orden fijo E01, E02, E03, E04.
 */
export class LoanValidationPolicy {
  private readonly specifications: readonly RejectionSpecification[];

  constructor(specifications?: readonly RejectionSpecification[]) {
    this.specifications = specifications ?? [
      new PrincipalRangeSpecification(),
      new TermRangeSpecification(),
      new MaturityAgeSpecification(),
      new MinimumCreditScoreSpecification(),
    ];
  }

  /**
   * Devuelve el código de la primera causa que falla, o null si no hay ninguna.
   * @rule R-004
   * @rule R-001
   * @rule R-002
   * @rule R-003
   * @rule R-005
   */
  firstViolation(application: LoanApplication): RejectionCode | null {
    const violated = this.specifications.find((spec) => spec.isViolatedBy(application));
    return violated === undefined ? null : violated.code;
  }
}

import { Decimal } from '../shared/decimal.ts';

interface RateTier {
  readonly minScore: Decimal;
  readonly rate: Decimal;
}

/**
 * Tasa anual base por tramos de puntaje, de mayor a menor umbral.
 */
export class BaseRatePolicy {
  private readonly tiers: readonly RateTier[] = [
    { minScore: Decimal.of(750), rate: Decimal.of('0.0899') },
    { minScore: Decimal.of(650), rate: Decimal.of('0.1299') },
    { minScore: Decimal.of(550), rate: Decimal.of('0.1899') },
  ];

  /**
   * Tasa base: >=750 0.0899; 650-749 0.1299; 550-649 0.1899. Con puntaje menor a 550 devuelve 0 (ya rechazado con E04).
   * @rule R-005
   */
  baseRate(creditScore: Decimal): Decimal {
    const tier = this.tiers.find((candidate) => creditScore.gte(candidate.minScore));
    return tier === undefined ? Decimal.of('0.0000') : tier.rate;
  }
}

import type { Decimal } from '../shared/decimal.ts';
import type { LoanApplication } from './LoanApplication.ts';

/**
 * Estrategia de ajuste de la tasa anual.
 */
export interface RateAdjustment {
  applies(application: LoanApplication): boolean;
  adjust(rate: Decimal): Decimal;
}

import { Decimal } from '../shared/decimal.ts';
import type { LoanApplication } from './LoanApplication.ts';
import type { RateAdjustment } from './RateAdjustment.ts';

export class PromotionalRateAdjustment implements RateAdjustment {
  private readonly minScore: Decimal = Decimal.of(800);
  private readonly maxTerm: Decimal = Decimal.of(60);
  private readonly discount: Decimal = Decimal.of('0.0025');

  /**
   * Aplica con puntaje >= 800 y plazo <= 60 meses.
   * @rule R-006
   */
  applies(application: LoanApplication): boolean {
    return application.creditScore.gte(this.minScore) && application.termMonths.lte(this.maxTerm);
  }

  /**
   * Descuenta 0.0025 de la tasa anual.
   * @rule R-006
   */
  adjust(rate: Decimal): Decimal {
    return rate.minus(this.discount);
  }
}

import { Decimal } from '../shared/decimal.ts';
import type { LoanApplication } from './LoanApplication.ts';
import type { RateAdjustment } from './RateAdjustment.ts';

export class LongTermSurchargeAdjustment implements RateAdjustment {
  private readonly threshold: Decimal = Decimal.of(120);
  private readonly surcharge: Decimal = Decimal.of('0.0050');

  /**
   * Aplica con plazo mayor que 120 meses, sea cual sea el puntaje.
   * @rule R-007
   */
  applies(application: LoanApplication): boolean {
    return application.termMonths.gt(this.threshold);
  }

  /**
   * Suma 0.0050 a la tasa anual.
   * @rule R-007
   */
  adjust(rate: Decimal): Decimal {
    return rate.plus(this.surcharge);
  }
}

import type { Decimal } from '../shared/decimal.ts';
import type { LoanApplication } from './LoanApplication.ts';
import type { RateAdjustment } from './RateAdjustment.ts';
import { BaseRatePolicy } from './BaseRatePolicy.ts';
import { PromotionalRateAdjustment } from './PromotionalRateAdjustment.ts';
import { LongTermSurchargeAdjustment } from './LongTermSurchargeAdjustment.ts';

/**
 * Calcula la tasa anual: base por puntaje más ajustes de promoción y de plazo largo.
 */
export class AnnualRateCalculator {
  private readonly basePolicy: BaseRatePolicy;
  private readonly adjustments: readonly RateAdjustment[];

  constructor(basePolicy?: BaseRatePolicy, adjustments?: readonly RateAdjustment[]) {
    this.basePolicy = basePolicy ?? new BaseRatePolicy();
    this.adjustments = adjustments ?? [new PromotionalRateAdjustment(), new LongTermSurchargeAdjustment()];
  }

  /**
   * Tasa anual final = base (R-005) con los ajustes R-006 y R-007.
   * @rule R-005
   * @rule R-006
   * @rule R-007
   */
  calculate(application: LoanApplication): Decimal {
    const base = this.basePolicy.baseRate(application.creditScore);
    return this.adjustments.reduce(
      (rate, adjustment) => (adjustment.applies(application) ? adjustment.adjust(rate) : rate),
      base,
    );
  }
}

import { Decimal } from '../shared/decimal.ts';

/**
 * Amortización francesa con las escalas intermedias del legacy.
 */
export class FrenchAmortization {
  private readonly monthsPerYear: Decimal = Decimal.of(12);
  private readonly one: Decimal = Decimal.of(1);

  /**
   * WS-RATE-MONTHLY = ROUND(tasa anual / 12, 9) mitad hacia arriba.
   * @rule R-008
   */
  monthlyRate(annualRate: Decimal): Decimal {
    return annualRate.dividedBy(this.monthsPerYear, 9, 'HALF_UP');
  }

  /**
   * WS-FACTOR = ROUND((1 + tasa mensual) ^ plazo, 9) mitad hacia arriba.
   * @rule R-009
   */
  capitalizationFactor(monthlyRate: Decimal, termMonths: number): Decimal {
    return this.one.plus(monthlyRate).pow(termMonths).setScale(9, 'HALF_UP');
  }

  /**
   * Cuota = ROUND(monto * tasa mensual * factor / (factor - 1), 2) mitad hacia arriba.
   * @rule R-010
   * @rule R-008
   * @rule R-009
   */
  monthlyPayment(principal: Decimal, annualRate: Decimal, termMonths: number): Decimal {
    const rate = this.monthlyRate(annualRate);
    const factor = this.capitalizationFactor(rate, termMonths);
    const numerator = principal.times(rate).times(factor);
    return numerator.dividedBy(factor.minus(this.one), 2, 'HALF_UP');
  }
}

import { Decimal } from '../shared/decimal.ts';

/**
 * Seguro mensual según la edad del cliente.
 */
export class InsurancePolicy {
  private readonly youngLimit: Decimal = Decimal.of(40);
  private readonly middleLimit: Decimal = Decimal.of(60);
  private readonly youngRate: Decimal = Decimal.of('0.00035');
  private readonly middleRate: Decimal = Decimal.of('0.00055');
  private readonly seniorRate: Decimal = Decimal.of('0.00095');

  /**
   * WS-INS-RATE: <40 0.00035; 40-59 0.00055; >=60 0.00095.
   * @rule R-011
   */
  insuranceRate(customerAge: Decimal): Decimal {
    if (customerAge.lt(this.youngLimit)) {
      return this.youngRate;
    }
    return customerAge.lt(this.middleLimit) ? this.middleRate : this.seniorRate;
  }

  /**
   * Seguro = ROUND(monto inicial * tasa de seguro, 2) mitad hacia arriba.
   * @rule R-012
   * @rule R-011
   */
  monthlyInsurance(principal: Decimal, customerAge: Decimal): Decimal {
    return principal.times(this.insuranceRate(customerAge)).setScale(2, 'HALF_UP');
  }
}

import { Decimal } from '../shared/decimal.ts';

/**
 * Totales del préstamo (exactos, sin ROUNDED).
 */
export class LoanTotals {
  /**
   * Interés total = cuota * plazo - monto (no incluye seguro).
   * @rule R-013
   */
  totalInterest(monthlyPayment: Decimal, termMonths: number, principal: Decimal): Decimal {
    return monthlyPayment.times(Decimal.of(termMonths)).minus(principal);
  }

  /**
   * Total pagado = (cuota + seguro) * plazo.
   * @rule R-014
   */
  totalPaid(monthlyPayment: Decimal, insurance: Decimal, termMonths: number): Decimal {
    return monthlyPayment.plus(insurance).times(Decimal.of(termMonths));
  }
}

import type { LoanApplication } from './LoanApplication.ts';
import { LoanEvaluation } from './LoanEvaluation.ts';
import type { LoanValidationPolicy } from './LoanValidationPolicy.ts';
import type { AnnualRateCalculator } from './AnnualRateCalculator.ts';
import type { FrenchAmortization } from './FrenchAmortization.ts';
import type { InsurancePolicy } from './InsurancePolicy.ts';
import type { LoanTotals } from './LoanTotals.ts';

/**
 * Servicio de dominio que orquesta la evaluación completa de un préstamo.
 */
export class LoanEvaluator {
  private readonly validation: LoanValidationPolicy;
  private readonly rates: AnnualRateCalculator;
  private readonly amortization: FrenchAmortization;
  private readonly insurance: InsurancePolicy;
  private readonly totals: LoanTotals;

  constructor(
    validation: LoanValidationPolicy,
    rates: AnnualRateCalculator,
    amortization: FrenchAmortization,
    insurance: InsurancePolicy,
    totals: LoanTotals,
  ) {
    this.validation = validation;
    this.rates = rates;
    this.amortization = amortization;
    this.insurance = insurance;
    this.totals = totals;
  }

  /**
   * Valida en orden, y solo si todo pasa calcula tasa, cuota, seguro y totales.
   * @rule R-004
   * @rule R-015
   */
  evaluate(application: LoanApplication): LoanEvaluation {
    const violation = this.validation.firstViolation(application);
    if (violation !== null) {
      return LoanEvaluation.rejected(violation);
    }
    return this.approve(application);
  }

  /**
   * Calcula los importes de una solicitud válida.
   * @rule R-015
   */
  private approve(application: LoanApplication): LoanEvaluation {
    const term = application.termMonthsAsInteger();
    const annualRate = this.rates.calculate(application);
    const payment = this.amortization.monthlyPayment(application.principal, annualRate, term);
    const insurance = this.insurance.monthlyInsurance(application.principal, application.customerAge);
    const totalInterest = this.totals.totalInterest(payment, term, application.principal);
    const totalPaid = this.totals.totalPaid(payment, insurance, term);
    return LoanEvaluation.approved(annualRate, payment, insurance, totalInterest, totalPaid);
  }
}

import type { LoanApplication } from '../../domain/loan/LoanApplication.ts';
import type { LoanEvaluation } from '../../domain/loan/LoanEvaluation.ts';

/**
 * Puerto de entrada: caso de uso de evaluación de préstamo.
 */
export interface EvaluateLoanUseCase {
  execute(application: LoanApplication): LoanEvaluation;
}

import type { LoanEvaluation } from '../../domain/loan/LoanEvaluation.ts';

/**
 * Puerto de salida: auditoría de resultados (sin datos personales).
 */
export interface AuditLogPort {
  record(evaluation: LoanEvaluation): void;
}

import type { LoanApplication } from '../domain/loan/LoanApplication.ts';
import type { LoanEvaluation } from '../domain/loan/LoanEvaluation.ts';
import type { LoanEvaluator } from '../domain/loan/LoanEvaluator.ts';
import type { AuditLogPort } from './ports/AuditLogPort.ts';
import type { EvaluateLoanUseCase } from './ports/EvaluateLoanUseCase.ts';

export class EvaluateLoanService implements EvaluateLoanUseCase {
  private readonly evaluator: LoanEvaluator;
  private readonly audit: AuditLogPort;

  constructor(evaluator: LoanEvaluator, audit: AuditLogPort) {
    this.evaluator = evaluator;
    this.audit = audit;
  }

  execute(application: LoanApplication): LoanEvaluation {
    const evaluation = this.evaluator.evaluate(application);
    this.audit.record(evaluation);
    return evaluation;
  }
}

import type { AuditLogPort } from '../application/ports/AuditLogPort.ts';
import type { LoanEvaluation } from '../domain/loan/LoanEvaluation.ts';

/**
 * Adaptador de auditoría simulado en memoria.
 */
export class InMemoryAuditLog implements AuditLogPort {
  private readonly entries: string[] = [];

  record(evaluation: LoanEvaluation): void {
    this.entries.push(evaluation.status + ':' + evaluation.errorCode);
  }

  list(): readonly string[] {
    return [...this.entries];
  }
}

import { Decimal } from '../domain/shared/decimal.ts';
import { LoanApplication } from '../domain/loan/LoanApplication.ts';
import { InvalidLoanInputError } from '../domain/loan/InvalidLoanInputError.ts';

const DECIMAL_PATTERN = /^\d+(\.\d+)?$/;
const INTEGER_PATTERN = /^\d+$/;

/**
 * Adaptador de entrada: convierte cadenas en tipos del dominio.
 */
export class LoanInputMapper {
  toApplication(input: Record<string, string>): LoanApplication {
    return new LoanApplication(
      this.decimalField(input, 'principal').setScale(2, 'DOWN'),
      this.integerField(input, 'term_months'),
      this.integerField(input, 'credit_score'),
      this.integerField(input, 'customer_age'),
    );
  }

  private decimalField(input: Record<string, string>, name: string): Decimal {
    return Decimal.of(this.rawValue(input, name, DECIMAL_PATTERN));
  }

  private integerField(input: Record<string, string>, name: string): Decimal {
    return Decimal.of(this.rawValue(input, name, INTEGER_PATTERN));
  }

  private rawValue(input: Record<string, string>, name: string, pattern: RegExp): string {
    const value = input[name];
    if (typeof value !== 'string' || !pattern.test(value.trim())) {
      throw new InvalidLoanInputError(name);
    }
    return value.trim();
  }
}

import type { LoanEvaluation } from '../domain/loan/LoanEvaluation.ts';

/**
 * Adaptador de salida: serializa el resultado como cadenas con su escala exacta.
 */
export class LoanOutputMapper {
  toOutput(evaluation: LoanEvaluation): Record<string, string> {
    return {
      status: evaluation.status,
      error_code: evaluation.errorCode,
      annual_rate: evaluation.annualRate.setScale(4, 'HALF_UP').toString(),
      monthly_payment: evaluation.monthlyPayment.setScale(2, 'HALF_UP').toString(),
      insurance: evaluation.insurance.setScale(2, 'HALF_UP').toString(),
      total_interest: evaluation.totalInterest.setScale(2, 'HALF_UP').toString(),
      total_paid: evaluation.totalPaid.setScale(2, 'HALF_UP').toString(),
    };
  }
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execute } from '../src/index.ts';

function request(principal: string, term: string, score: string, age: string): Record<string, string> {
  return { principal, term_months: term, credit_score: score, customer_age: age };
}

test('E01 cuando el monto está fuera de rango', () => {
  const out = execute(request('999.99', '60', '800', '30'));
  assert.equal(out.status, 'REJECTED');
  assert.equal(out.error_code, 'E01');
  assert.equal(out.monthly_payment, '0.00');
  assert.equal(out.annual_rate, '0.0000');
});

test('E02 cuando el plazo es menor que 6', () => {
  assert.equal(execute(request('5000.00', '5', '800', '30')).error_code, 'E02');
});

test('E03 cuando la edad al vencimiento supera 75', () => {
  assert.equal(execute(request('5000.00', '72', '800', '70')).error_code, 'E03');
  assert.equal(execute(request('5000.00', '71', '800', '70')).status, 'APPROVED');
});

test('E04 cuando el puntaje es menor que 550', () => {
  assert.equal(execute(request('5000.00', '60', '549', '30')).error_code, 'E04');
});

test('aprobado con promoción y seguro', () => {
  const out = execute(request('10000.00', '60', '800', '30'));
  assert.equal(out.status, 'APPROVED');
  assert.equal(out.error_code, '');
  assert.equal(out.annual_rate, '0.0874');
  assert.equal(out.insurance, '3.50');
});

test('recargo por plazo largo', () => {
  assert.equal(execute(request('10000.00', '121', '750', '30')).annual_rate, '0.0949');
});
